"use strict";
const assert = require('node:assert/strict');
const cp = require('node:child_process');
const path = 'workspaces/programs/selection-element-specification.md';
const apiPath = 'repos/BestNameYet/Terminals/contents/' + path;
const expectedSha = '96ed3858590050d54905148567af4ff193508784';
const call = args => JSON.parse(cp.execFileSync('gh', ['api', ...args], {encoding:'utf8', maxBuffer:1024*1024}));
const before = call([apiPath]);
assert.equal(before.sha, expectedSha, 'Unexpected source revision; refusing to overwrite');
const original = Buffer.from(before.content.replace(/\s/g,''), 'base64').toString('utf8');
const startMarker = '- Runtime expressions beginning with `# Programs — Selection Element Specification';
const nextMarker = '\n- `$id` denotes the same runtime variable';
const start = original.indexOf(startMarker);
const end = original.indexOf(nextMarker, start);
assert(start >= 0 && end > start, 'Exact damaged section not found');
assert.equal(original.indexOf(startMarker, start + 1), -1, 'Duplicate damaged start markers');
const repair = '- Runtime expressions beginning with `$` remain semantically distinct from literal strings. A compiler must encode them into a valid JSON interaction envelope before delivery; the exact encoded expression representation remains an open interface decision.';
const updated = original.slice(0,start) + repair + original.slice(end);
assert.equal(updated.split(repair).length, 2);
assert.equal(updated.match(/# Programs — Selection Element Specification/g).length, 1);
assert.equal(updated.match(/\*\*Specification version:\*\* 0\.2\.0/g).length, 1);
const saved = call([apiPath, '--method', 'PUT', '-f', 'message=Repair duplicated selection template language paragraph', '-f', 'sha='+before.sha, '-f', 'content='+Buffer.from(updated,'utf8').toString('base64')]);
const after = call([apiPath]);
const remote = Buffer.from(after.content.replace(/\s/g,''), 'base64').toString('utf8');
assert.equal(remote, updated, 'Remote readback differs from intended content');
assert.equal(after.sha, saved.content.sha, 'Returned file SHA differs from remote');
console.log(JSON.stringify({status:'verified', path, previous_blob_sha:before.sha, new_blob_sha:after.sha, commit_sha:saved.commit.sha, removed_chars:original.length-updated.length, version:'0.2.0'}));
